package com.nigson.acceptance.order;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import com.nigson.commerce.order.*;
import com.nigson.commerce.inventory.InventoryValues;
import com.nigson.shared.problem.Problem;
import com.nigson.shared.security.*;
import static org.assertj.core.api.Assertions.*;
class OrderPersistenceTest {
 OrderFixture f;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null&&System.getenv("NIGSON_TEST_ORDER_PAYSTACK")!=null,"order-check supplies isolated native database and stateful mock");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_ORDER_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");f=new OrderFixture(new JdbcTemplate(ds),new DataSourceTransactionManager(ds));}
 @AfterEach void cleanup(){if(f!=null)f.close();}
 private int count(String table,String where,Object...args){return f.jdbc.queryForObject("SELECT count(*) FROM commerce."+table+" WHERE "+where,Integer.class,args);}
 @Test void atomicSnapshotReservesThenInitializesWithStableReferenceAndProgressiveReplay(){var result=f.checkout("checkout");var order=result.order();assertThat(order.status()).isEqualTo("PENDING");assertThat(order.paymentStatus()).isEqualTo("PENDING");assertThat(order.totals().grandTotal()).isEqualTo("28.13");assertThat(order.lines()).hasSize(1);assertThat(order.lines().getFirst().quantity()).isEqualTo("2");assertThat(order.address().countryCode()).isEqualTo("NG");assertThat(result.payment().state()).isEqualTo("PENDING");assertThat(result.payment().checkoutUrl()).isNull();assertThat(result.payment().reference()).matches("nigson-[a-f0-9]{32}");assertThat(f.stock("reserved")).isEqualByComparingTo("2");assertThat(f.stock("allocated")).isZero();assertThat(f.stock("on_hand")).isEqualByComparingTo("5");assertThat(f.checkout("checkout")).isEqualTo(result);assertThat(f.checkout("second-http-key")).isEqualTo(result);assertThat(count("sales_order","market_id=?",f.prices.market)).isEqualTo(1);assertThat(count("payment_attempt","order_id=?",order.id())).isEqualTo(1);assertThat(count("order_total_component","order_id=?",order.id())).isEqualTo(4);assertThat(count("order_status_history","order_id=?",order.id())).isEqualTo(1);assertThat(count("outbox_event","aggregate_id=? AND event_type='order.pending.v1'",order.id())).isEqualTo(1);assertThat(count("audit_record","resource_id=? AND action='ORDER_CHECKOUT'",order.id())).isEqualTo(1);assertThat(f.state().path("operations").size()).isEqualTo(1);assertThat(f.prices.metrics.get("nigson.order.commands").tag("operation","CHECKOUT").counter().count()).isEqualTo(1);f.jdbc.update("UPDATE commerce.product SET name='Synthetic changed later name' WHERE id=?",f.prices.marketFixture.product);assertThat(f.service.get(f.prices.customer,order.id()).lines().getFirst().name()).isEqualTo(order.lines().getFirst().name());}
 @Test void staleAddressPriceMarketAndHashRejectBeforeIntentOrHttp(){f.jdbc.update("UPDATE commerce.address SET line1='Synthetic changed destination' WHERE id=?",f.prices.address);assertThatThrownBy(()->f.checkout("stale-address")).hasMessage("CHECKOUT_REPRICE_REQUIRED");f.jdbc.update("UPDATE commerce.address SET line1='Synthetic offline address' WHERE id=?",f.prices.address);f.jdbc.update("UPDATE commerce.price_entry SET unit_amount=12.35 WHERE sku_id=? AND minimum_quantity=1",f.prices.sku);assertThatThrownBy(()->f.checkout("stale-price")).hasMessage("CHECKOUT_REPRICE_REQUIRED");f.jdbc.update("UPDATE commerce.price_entry SET unit_amount=12.34 WHERE sku_id=? AND minimum_quantity=1",f.prices.sku);f.jdbc.update("UPDATE commerce.market SET policy_revision=policy_revision+1 WHERE id=?",f.prices.market);assertThatThrownBy(()->f.checkout("stale-policy")).hasMessage("CHECKOUT_REPRICE_REQUIRED");assertThatThrownBy(()->f.service.checkout(f.prices.customer,new OrderValues.CheckoutInput(f.quote.id(),"b".repeat(64),"HOSTED"),"bad-hash",UUID.randomUUID())).hasMessage("CHECKOUT_REPRICE_REQUIRED");assertThat(count("sales_order","market_id=?",f.prices.market)).isZero();assertThat(f.stock("reserved")).isZero();assertThat(f.state().path("operations")).isEmpty();}
 @Test void auditFailureRollsBackAllIntentAndStockBeforeProviderThenSameKeyCanRetry(){f.prices.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->f.checkout("rollback")).isInstanceOf(org.springframework.dao.DataAccessException.class);}finally{f.prices.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}assertThat(count("sales_order","market_id=?",f.prices.market)).isZero();assertThat(f.stock("reserved")).isZero();assertThat(f.jdbc.queryForObject("SELECT status FROM commerce.cart WHERE id=?",String.class,f.prices.cart)).isEqualTo("ACTIVE");assertThat(f.jdbc.queryForObject("SELECT status FROM commerce.carrier_quote WHERE id=?",String.class,f.prices.carrier)).isEqualTo("QUOTED");assertThat(f.state().path("operations")).isEmpty();assertThat(count("idempotency_record","operation='API-037' AND request_key='rollback' AND state='SUCCEEDED'")).isZero();assertThat(f.checkout("rollback").payment().state()).isEqualTo("PENDING");}
 @Test void actualIndependentHttpVerificationAllocatesOnceAndProofRemainsMinimal(){var result=f.checkout("paid");f.progress(result,"success");f.payments.inspect(result.order().id(),UUID.randomUUID());var paid=f.service.get(f.prices.customer,result.order().id());assertThat(paid.status()).isEqualTo("PAID");assertThat(paid.paymentStatus()).isEqualTo("PAID");assertThat(f.stock("reserved")).isZero();assertThat(f.stock("allocated")).isEqualByComparingTo("2");assertThat(f.stock("on_hand")).isEqualByComparingTo("5");assertThat(count("payment_transaction","attempt_id=?",result.payment().attemptId())).isEqualTo(1);f.payments.inspect(paid.id(),UUID.randomUUID());f.tx.executeWithoutResult(s->f.lifecycle.settled(paid.id(),UUID.randomUUID()));assertThat(f.checkout("paid").order()).isEqualTo(paid);assertThat(count("inventory_movement","order_id=? AND movement_type='SETTLE'",paid.id())).isEqualTo(1);assertThat(count("outbox_event","aggregate_id=? AND event_type='order.paid.v1'",paid.id())).isEqualTo(1);var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-121")).findFirst().orElseThrow();var proof=new PrivateWorkload.Proof("nigson-experience","synthetic-service",route,null);var input=new OrderValues.ProofInput(f.prices.customer.party(),paid.lines().getFirst().id(),f.prices.marketFixture.product);assertThat(f.service.proof(proof,input).eligible()).isTrue();assertThat(f.service.proof(proof,new OrderValues.ProofInput(UUID.randomUUID(),input.orderLineId(),input.productId())).eligible()).isFalse();assertThatThrownBy(()->f.service.proof(new PrivateWorkload.Proof("nigson-integration","wrong-service",route,null),input)).hasMessage("ACCESS_DENIED");var processed=f.service.processing(f.operations,paid.id(),paid.version(),"Synthetic authorized paid processing","process",UUID.randomUUID());assertThat(processed.status()).isEqualTo("PROCESSING");assertThat(processed.paymentStatus()).isEqualTo("PAID");assertThat(f.service.processing(f.operations,paid.id(),paid.version(),"Synthetic authorized paid processing","process",UUID.randomUUID())).isEqualTo(processed);assertThatThrownBy(()->f.service.processing(f.operations,paid.id(),paid.version(),"Synthetic authorized paid processing","stale",UUID.randomUUID())).hasMessage("VERSION_MISMATCH");}
 @Test void uncertainPendingCannotCancelButVerifiedFailureReleasesAndExpiresCart(){var result=f.checkout("cancel");assertThatThrownBy(()->f.service.cancelled(f.prices.customer,result.order().id(),result.order().version(),"Customer requests cancellation","uncertain-cancel",UUID.randomUUID())).hasMessage("PROVIDER_OUTCOME_UNKNOWN");assertThat(f.stock("reserved")).isEqualByComparingTo("2");f.progress(result,"failed");f.payments.inspect(result.order().id(),UUID.randomUUID());var failed=f.service.get(f.prices.customer,result.order().id());var cancelled=f.service.cancelled(f.prices.customer,failed.id(),failed.version(),"Customer requests cancellation","cancel",UUID.randomUUID());assertThat(cancelled.status()).isEqualTo("CANCELLED");assertThat(cancelled.paymentStatus()).isEqualTo("FAILED");assertThat(f.stock("reserved")).isZero();assertThat(f.stock("on_hand")).isEqualByComparingTo("5");assertThat(f.jdbc.queryForObject("SELECT status FROM commerce.cart WHERE id=?",String.class,f.prices.cart)).isEqualTo("EXPIRED");assertThat(f.service.cancelled(f.prices.customer,failed.id(),failed.version(),"Customer requests cancellation","cancel",UUID.randomUUID())).isEqualTo(cancelled);}
 @Test void lateSuccessReclaimsReleasedStockAndRetainsOneFinancialTruth(){var result=f.checkout("late");f.releaseUncertain(result.order().id());assertThat(f.stock("reserved")).isZero();f.progress(result,"success");f.payments.inspect(result.order().id(),UUID.randomUUID());assertThat(f.service.get(f.prices.customer,result.order().id()).status()).isEqualTo("PAID");assertThat(f.stock("allocated")).isEqualByComparingTo("2");assertThat(count("payment_transaction","attempt_id=?",result.payment().attemptId())).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT status FROM commerce.cart WHERE id=?",String.class,f.prices.cart)).isEqualTo("CONVERTED");}
 @Test void lateSuccessWithMissingStockPersistsPaidHoldAndNeverAutoResolvesIt(){var result=f.checkout("late-hold");f.releaseUncertain(result.order().id());long version=f.jdbc.queryForObject("SELECT version FROM commerce.inventory_balance WHERE id=?",Long.class,f.balance);f.inventory.adjust(f.operations,new InventoryValues.Adjustment(f.prices.sku,f.location,"-5","Synthetic stock consumed before late settlement"),version,"consume",UUID.randomUUID());f.progress(result,"success");f.payments.inspect(result.order().id(),UUID.randomUUID());var held=f.service.get(f.prices.customer,result.order().id());assertThat(held.status()).isEqualTo("PAYMENT_HOLD");assertThat(held.paymentStatus()).isEqualTo("PAID");assertThat(held.fulfillmentStatus()).isEqualTo("HOLD");assertThat(count("payment_transaction","attempt_id=?",result.payment().attemptId())).isEqualTo(1);assertThat(f.stock("allocated")).isZero();assertThat(f.stock("on_hand")).isZero();assertThat(f.tx.<OrderValues.Order>execute(s->f.lifecycle.settled(held.id(),UUID.randomUUID()))).isEqualTo(held);assertThatThrownBy(()->f.service.processing(f.operations,held.id(),held.version(),"Synthetic held order denial","hold-process",UUID.randomUUID())).hasMessage("INVALID_TRANSITION");}
 @Test void timeoutAfterAcceptanceRetainsUnknownAndRepeatsNeverReinitialize(){f.admin("configure",Map.of("scenario","timeout-after-acceptance"));var result=f.checkout("unknown");assertThat(result.payment().state()).isEqualTo("UNKNOWN");assertThat(result.payment().checkoutUrl()).isNull();assertThat(f.state().path("operations").size()).isEqualTo(1);assertThat(f.checkout("unknown")).isEqualTo(result);assertThat(f.checkout("new-key")).isEqualTo(result);assertThat(f.state().path("operations").size()).isEqualTo(1);f.progress(result,"success");f.payments.inspect(result.order().id(),UUID.randomUUID());assertThat(f.service.get(f.prices.customer,result.order().id()).status()).isEqualTo("PAID");assertThat(f.stock("allocated")).isEqualByComparingTo("2");}
 @Test void currentAuthorityBeforeReplayAndRetailOwnerDenialAndStaffFilters(){var result=f.checkout("owner");var buyer=f.secondBuyer();assertThatThrownBy(()->f.service.get(buyer.actor(),result.order().id())).hasMessage("NOT_FOUND");var q=new OrderValues.Query(null,null,null,null,null,0,20,"createdAt,desc");assertThat(f.service.list(buyer.actor(),q,false).items()).isEmpty();assertThat(f.service.list(f.prices.customer,q,false).items()).hasSize(1);assertThatThrownBy(()->f.service.list(f.prices.customer,q,true)).hasMessage("ACCESS_DENIED");assertThat(f.service.list(f.operations,q,true).items()).hasSize(1);f.jdbc.update("UPDATE commerce.party SET status='SUSPENDED' WHERE id=?",f.prices.customer.party());assertThatThrownBy(()->f.checkout("owner")).hasMessage("ACCESS_DENIED");assertThat(count("sales_order","market_id=?",f.prices.market)).isEqualTo(1);}
 @Test void simultaneousBuyersCannotReserveTheSameLastUnits()throws Exception{long version=f.jdbc.queryForObject("SELECT version FROM commerce.inventory_balance WHERE id=?",Long.class,f.balance);f.inventory.adjust(f.operations,new InventoryValues.Adjustment(f.prices.sku,f.location,"-3","Synthetic final two units race"),version,"two-units",UUID.randomUUID());var second=f.secondBuyer();try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var a=pool.submit(()->{start.await();try{return (Object)f.checkout("race-one");}catch(Problem.Failure e){return e.getMessage();}});var b=pool.submit(()->{start.await();try{return (Object)f.service.checkout(second.actor(),second.input(),"race-two",UUID.randomUUID());}catch(Problem.Failure e){return e.getMessage();}});start.countDown();var results=List.of(a.get(20,TimeUnit.SECONDS),b.get(20,TimeUnit.SECONDS));assertThat(results.stream().filter(x->x instanceof OrderValues.Checkout).count()).isEqualTo(1);for(var result:results)if(result instanceof String error)assertThat(error).isIn("ORDER_RULE_VIOLATION","IDEMPOTENCY_IN_PROGRESS");}assertThat(count("sales_order","market_id=?",f.prices.market)).isEqualTo(1);assertThat(f.stock("reserved")).isEqualByComparingTo("2");assertThat(f.stock("on_hand")).isEqualByComparingTo("2");assertThat(f.state().path("operations").size()).isEqualTo(1);}
 @Test void localApplicationPortJoinsCallerRollbackAndNeverCallsProvider(){f.tx.executeWithoutResult(status->{var result=f.service.pending(f.prices.customer,f.input,UUID.randomUUID());assertThat(result.payment().state()).isEqualTo("CREATED");assertThat(f.stock("reserved")).isEqualByComparingTo("2");assertThat(f.state().path("operations")).isEmpty();status.setRollbackOnly();});assertThat(count("sales_order","market_id=?",f.prices.market)).isZero();assertThat(f.stock("reserved")).isZero();assertThat(f.jdbc.queryForObject("SELECT status FROM commerce.cart WHERE id=?",String.class,f.prices.cart)).isEqualTo("ACTIVE");assertThat(f.jdbc.queryForObject("SELECT status FROM commerce.carrier_quote WHERE id=?",String.class,f.prices.carrier)).isEqualTo("QUOTED");assertThat(f.state().path("operations")).isEmpty();}
 @Test void duplicateCheckoutRaceHasOneBusinessEffectAndOneHttpInitialization()throws Exception{try(var pool=Executors.newFixedThreadPool(12)){var start=new CountDownLatch(1);var futures=new ArrayList<Future<Object>>();for(int n=0;n<12;n++)futures.add(pool.submit(()->{start.await();try{return f.checkout("duplicate-checkout");}catch(Problem.Failure|com.nigson.commerce.platform.PlatformStore.Conflict failure){return failure.getMessage();}}));start.countDown();for(var future:futures){var result=future.get(20,TimeUnit.SECONDS);if(result instanceof OrderValues.Checkout checkout)assertThat(checkout.order().totals().grandTotal()).isEqualTo("28.13");else assertThat(result).isEqualTo("IDEMPOTENCY_IN_PROGRESS");}}var accepted=f.checkout("duplicate-checkout");assertThat(accepted.payment().state()).isEqualTo("PENDING");assertThat(count("sales_order","market_id=?",f.prices.market)).isEqualTo(1);assertThat(count("inventory_movement","order_id=? AND movement_type='RESERVE'",accepted.order().id())).isEqualTo(1);assertThat(count("audit_record","resource_id=? AND action='ORDER_CHECKOUT'",accepted.order().id())).isEqualTo(1);assertThat(f.state().path("operations").size()).isEqualTo(1);assertThat(java.util.stream.StreamSupport.stream(f.state().path("journal").spliterator(),false).filter(x->x.path("route").asString().equals("/transaction/initialize")).count()).isEqualTo(1);assertThatThrownBy(()->f.service.checkout(f.prices.customer,new OrderValues.CheckoutInput(f.quote.id(),"b".repeat(64),"HOSTED"),"duplicate-checkout",UUID.randomUUID())).hasMessage("IDEMPOTENCY_HASH_MISMATCH");}
 @Test void persistedAttemptModeCannotBeReusedAgainstAnotherProviderMode(){var result=f.checkout("mode");f.jdbc.update("UPDATE commerce.payment_attempt SET provider_mode='LIVE' WHERE id=?",result.payment().attemptId());f.progress(result,"success");assertThatThrownBy(()->f.payments.inspect(result.order().id(),UUID.randomUUID())).hasMessage("PROVIDER_MODE_MISMATCH");assertThat(count("payment_transaction","attempt_id=?",result.payment().attemptId())).isZero();assertThat(f.stock("allocated")).isZero();assertThat(f.stock("reserved")).isEqualByComparingTo("2");}

 @Test void verifiedFinancialTruthDoesNotClearAnExistingFulfillmentHold(){var result=f.checkout("existing-hold");f.jdbc.update("UPDATE commerce.sales_order SET hold_reason='SYNTHETIC_OFFLINE_REVIEW' WHERE id=?",result.order().id());f.progress(result,"success");f.payments.inspect(result.order().id(),UUID.randomUUID());var held=f.service.get(f.prices.customer,result.order().id());assertThat(held.paymentStatus()).isEqualTo("PAID");assertThat(held.status()).isEqualTo("PAYMENT_HOLD");assertThat(f.jdbc.queryForObject("SELECT hold_reason FROM commerce.sales_order WHERE id=?",String.class,held.id())).isEqualTo("SYNTHETIC_OFFLINE_REVIEW");assertThat(f.stock("allocated")).isZero();assertThat(f.stock("reserved")).isEqualByComparingTo("2");assertThat(count("payment_transaction","attempt_id=?",result.payment().attemptId())).isEqualTo(1);assertThat(f.tx.<OrderValues.Order>execute(s->f.lifecycle.settled(held.id(),UUID.randomUUID()))).isEqualTo(held);}

 @Test void malformedVerifiedTimestampRemainsUnknownUntilActualReconciliation(){var result=f.checkout("malformed-verification");f.progress(result,"success");f.admin("configure",Map.of("scenario","invalid-verification"));f.payments.inspect(result.order().id(),UUID.randomUUID());assertThat(f.jdbc.queryForObject("SELECT state FROM commerce.payment_attempt WHERE id=?",String.class,result.payment().attemptId())).isEqualTo("UNKNOWN");assertThat(count("payment_transaction","attempt_id=?",result.payment().attemptId())).isZero();assertThat(f.stock("allocated")).isZero();assertThat(f.stock("reserved")).isEqualByComparingTo("2");f.admin("configure",Map.of("scenario","success"));f.payments.inspect(result.order().id(),UUID.randomUUID());assertThat(f.service.get(f.prices.customer,result.order().id()).status()).isEqualTo("PAID");assertThat(count("payment_transaction","attempt_id=?",result.payment().attemptId())).isEqualTo(1);assertThat(f.state().path("operations").size()).isEqualTo(1);}

 @Test void inconsistentPaidCancelledStateCannotSilentlyReplaySettlement(){var result=f.checkout("inconsistent-state");f.progress(result,"success");f.payments.inspect(result.order().id(),UUID.randomUUID());f.jdbc.update("UPDATE commerce.sales_order SET status='CANCELLED' WHERE id=?",result.order().id());assertThatThrownBy(()->f.tx.execute(s->f.lifecycle.settled(result.order().id(),UUID.randomUUID()))).hasMessage("ORDER_RULE_VIOLATION");assertThat(count("payment_transaction","attempt_id=?",result.payment().attemptId())).isEqualTo(1);assertThat(f.stock("allocated")).isEqualByComparingTo("2");assertThat(count("inventory_movement","order_id=? AND movement_type='SETTLE'",result.order().id())).isEqualTo(1);}

 @Test void historicalOrganizationReadsRequireCurrentMembershipWithoutBuyingEntitlement(){UUID org=f.prices.organization();var input=f.organizationQuote(org);var result=f.service.checkout(f.prices.customer,input,"organization-checkout",UUID.randomUUID());assertThat(result.order().totals().grandTotal()).isEqualTo("19.45");var other=f.secondBuyer();UUID membership=UUID.randomUUID();f.jdbc.update("INSERT INTO commerce.organization_membership(id,created_by,updated_by,organization_id,party_id,role,status) VALUES (?,'test','test',?,?,'BUYER','ACTIVE')",membership,org,other.actor().party());f.jdbc.update("UPDATE commerce.account_entitlement SET status='SUSPENDED' WHERE organization_id=?",org);assertThat(f.service.get(other.actor(),result.order().id())).isEqualTo(result.order());var query=new OrderValues.Query(org,null,null,null,null,0,20,"createdAt,desc");assertThat(f.service.list(other.actor(),query,false).items()).hasSize(1);assertThatThrownBy(()->f.service.checkout(f.prices.customer,input,"organization-checkout",UUID.randomUUID())).hasMessage("ACCESS_DENIED");f.jdbc.update("UPDATE commerce.organization_membership SET status='REVOKED' WHERE id=?",membership);assertThatThrownBy(()->f.service.get(other.actor(),result.order().id())).hasMessage("NOT_FOUND");assertThatThrownBy(()->f.service.list(other.actor(),query,false)).hasMessage("NOT_FOUND");assertThat(f.service.list(other.actor(),new OrderValues.Query(null,null,null,null,null,0,20,"createdAt,desc"),false).items()).isEmpty();assertThat(f.state().path("operations").size()).isEqualTo(1);}

 @Test void accountChangeAfterCheckoutQuoteRejectsBeforeOrderReservationAndPaymentHttp(){f.jdbc.update("UPDATE commerce.carrier_quote SET provider_snapshot=jsonb_set(provider_snapshot,'{accountHash}',?::jsonb) WHERE id=?","\""+"2".repeat(64)+"\"",f.prices.carrier);assertThatThrownBy(()->f.checkout("rotated-account")).hasMessage("PROVIDER_MODE_MISMATCH");assertThat(count("sales_order","market_id=?",f.prices.market)).isZero();assertThat(f.stock("reserved")).isZero();assertThat(f.state().path("operations")).isEmpty();}
 @Test void originalAccountIsHashBoundAndFrozenIndependentOfLaterQuoteChanges(){var accepted=f.checkout("frozen-account");String before=f.jdbc.queryForObject("SELECT carrier_snapshot::text FROM commerce.sales_order WHERE id=?",String.class,accepted.order().id());var node=com.nigson.shared.events.EventCodec.JSON.readTree(before);assertThat(node.path("accountHash").asString()).isEqualTo("1".repeat(64));assertThat(node.path("providerSnapshot").path("accountHash").asString()).isEqualTo("1".repeat(64));assertThat(f.jdbc.queryForObject("SELECT commercial_snapshot->>'carrierAccountHash' FROM commerce.sales_order WHERE id=?",String.class,accepted.order().id())).isEqualTo("1".repeat(64));f.jdbc.update("UPDATE commerce.carrier_quote SET provider_snapshot=jsonb_set(provider_snapshot,'{accountHash}',?::jsonb) WHERE id=?","\""+"2".repeat(64)+"\"",f.prices.carrier);assertThat(f.checkout("frozen-account").order().id()).isEqualTo(accepted.order().id());assertThat(f.jdbc.queryForObject("SELECT carrier_snapshot::text FROM commerce.sales_order WHERE id=?",String.class,accepted.order().id())).isEqualTo(before);assertThat(f.state().path("operations")).hasSize(1);}

}
